/**
 * Worker bindings. `Env` is generated by `wrangler types` from wrangler.jsonc (vars, Hyperdrive, R2, KV, AI, Queue).
 * Vars are widened to `string` because environments override them; secrets are set with `wrangler secret put`.
 */
export type Secrets = {
  SESSION_SECRET?: string;
  ENCRYPTION_KEY?: string;
  OPENAI_API_KEY?: string;
  ANTHROPIC_API_KEY?: string;
  GOOGLE_API_KEY?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  MICROSOFT_CLIENT_ID?: string;
  MICROSOFT_CLIENT_SECRET?: string;
  APPLE_CLIENT_ID?: string;
  APPLE_TEAM_ID?: string;
  APPLE_KEY_ID?: string;
  APPLE_PRIVATE_KEY?: string;
  STRIPE_SECRET_KEY?: string;
  STRIPE_WEBHOOK_SECRET?: string;
  RESEND_API_KEY?: string;
  EMAIL_FROM?: string;
  CRON_SECRET?: string;
  /** Shared HMAC secret for super-admin SSO from the suite landing page (GET /api/auth/sso). Endpoint returns 503 when unset. */
  SAAS_SSO_SECRET?: string;
};

type VarKeys = "APP_NAME" | "APP_VERSION" | "WEB_ORIGIN" | "WEB_ORIGINS" | "SSO_REDIRECT_TO" | "API_ORIGIN" | "JOB_MODE" | "SESSION_TTL_HOURS" | "MAX_UPLOAD_BYTES" | "EMBEDDING_MODEL" | "EMBEDDING_DIMENSIONS";

export type Bindings = Omit<Env, VarKeys> & Record<VarKeys, string> & Secrets;

export type QueueJob =
  | { type: "PROCESS_DOCUMENT"; document_id: string; correlation_id: string }
  | { type: "PROCESS_UPLOAD"; upload_id: string; correlation_id: string }
  | { type: "SUMMARIZE_CONVERSATION"; conversation_id: string; correlation_id: string };
